<script setup lang="ts">
import { computed,ref } from 'vue'
import { usePlatform } from '../stores/platform'
import { useContinuity } from '../stores/continuity'
import { download } from '../utils/files'
import PageHead from '../components/PageHead.vue'
import Modal from '../components/Modal.vue'
import type { ArchiveAttachment } from '../domain/continuity'
const s=usePlatform(),c=useContinuity(),sessionId=ref(s.data.sessions[0]?.id||''),personId=ref(''),kind=ref('线下答卷'),opened=ref(false),preview=ref<ArchiveAttachment|null>(null)
const members=computed(()=>c.data.enrollments.filter(e=>e.sessionId===sessionId.value)),bundle=computed(()=>personId.value?c.archive(sessionId.value,personId.value):null)
function view(id:string){personId.value=id;opened.value=true}
function count(id:string,type:string){if(type==='attempts')return s.data.attempts.filter(a=>a.sessionId===sessionId.value&&a.personId===id).length;if(type==='skills')return s.data.skills.filter(k=>k.sessionId===sessionId.value&&k.personId===id).length;return c.data.attachments.filter(a=>a.sessionId===sessionId.value&&a.personId===id).length}
function sample(){s.run(()=>c.attach({sessionId:sessionId.value,personId:personId.value,name:`${kind.value}-${bundle.value?.member?.name}.txt`,kind:kind.value,mime:'text/plain',content:`合成${kind.value}\n考生：${bundle.value?.member?.name}\n准考证：${bundle.value?.member?.ticket}\n场次：${bundle.value?.session?.name}\n此文件为可下载的本地样例，用于检查归档关联。`} ))}
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(file.size>1024*1024)throw new Error('文件不得超过1MB');if(!['text/plain','application/pdf','image/png','image/jpeg'].includes(file.type))throw new Error('支持TXT、PDF、PNG和JPEG');const content=await new Promise<string>((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result));reader.onerror=()=>reject(new Error('读取文件失败'));if(file.type==='text/plain')reader.readAsText(file);else reader.readAsDataURL(file)});c.attach({sessionId:sessionId.value,personId:personId.value,name:file.name,kind:kind.value,mime:file.type,content})}catch(e){s.notify(e instanceof Error?e.message:'上传失败',true)}finally{input.value=''}}
function downloadAttachment(a:ArchiveAttachment){if(a.mime==='text/plain')download(a.name,a.content);else{const el=document.createElement('a');el.href=a.content;el.download=a.name;el.click()}}
</script>
<template><PageHead title="考生综合档案" subtitle="按场次和考生汇集线上答卷、评阅记录、技能评分与线下材料。" eyebrow="考试与评价 / 档案"><RouterLink class="button" to="/results/list">成绩管理</RouterLink></PageHead><section class="panel"><div class="filter-bar"><label class="inline-label">考试场次<select v-model="sessionId"><option v-for="e in s.data.sessions" :value="e.id">{{e.name}}</option></select></label><span class="push-right">{{members.length}}名考生</span></div><table><thead><tr><th>考生 / 准考证</th><th>线上答卷</th><th>技能任务</th><th>线下材料</th><th>操作</th></tr></thead><tbody><tr v-for="e in members"><td>{{e.name}}<small>{{e.ticket}}</small></td><td>{{count(e.personId,'attempts')}}</td><td>{{count(e.personId,'skills')}}</td><td>{{count(e.personId,'attachments')}}</td><td><button class="text-button" @click="view(e.personId)">查看综合档案</button></td></tr></tbody></table><p v-if="!members.length" class="muted">本场尚未编排考生名单。</p></section>
<Modal v-if="opened&&bundle" :title="bundle.member?.name+' · 综合档案'" wide @close="opened=false"><p>{{bundle.session?.name}} · {{bundle.member?.ticket}}</p><h3>线上答卷与评阅</h3><p v-if="!bundle.attempts.length" class="muted">尚未产生线上答卷</p><div v-for="a in bundle.attempts" class="notice">{{a.id}} · {{a.status}} · 客观题 {{a.objective}} 分 · 主观题 {{a.subjective??'待评阅'}} · 版本 V{{a.version}}<p>考生签名：{{a.signature||'尚未交卷'}}</p><p v-for="m in bundle.marks.filter(m=>m.attemptId===a.id)">{{m.status}} · 评分 {{Object.entries(m.scores).map(([r,v])=>r+' '+v).join(' / ')}} · 最终分 {{m.final??'待核定'}}</p></div><h3>技能评分</h3><p v-if="!bundle.skills.length" class="muted">尚未配发技能任务</p><div v-for="k in bundle.skills" class="notice">{{k.questionSnapshot?.title||k.questionId}} · {{k.status}} · 考评员 {{k.assessor}}<p v-if="k.status==='已提交'">得分 {{k.scores.reduce((a,b)=>a+b,0)}} · {{k.note||'无附加意见'}}</p></div><h3>线下归档材料</h3><div class="filter-bar"><select v-model="kind"><option>线下答卷</option><option>现场评分表</option><option>考场记录</option></select><button class="button" @click="sample">添加合成材料</button><label class="button">上传材料<input type="file" accept=".txt,.pdf,.png,.jpg,.jpeg" style="display:none" @change="upload"/></label></div><p class="muted">支持TXT、PDF、PNG、JPEG，单个文件不超过1MB；保存在当前浏览器。</p><table><thead><tr><th>材料</th><th>归档记录</th><th>操作</th></tr></thead><tbody><tr v-for="a in bundle.attachments"><td>{{a.name}}<small>{{a.kind}}</small></td><td>{{a.actor}}<small>{{a.time}}</small></td><td><div class="action-group"><button class="text-button" @click="preview=a">预览</button><button class="text-button" @click="downloadAttachment(a)">下载</button></div></td></tr></tbody></table><template #footer><button class="button primary" @click="download('考生综合档案-'+bundle.member?.ticket+'.json',JSON.stringify(bundle,null,2),'application/json')">下载完整档案</button></template></Modal>
<Modal v-if="preview" :title="preview.name" wide @close="preview=null"><pre v-if="preview.mime==='text/plain'" style="white-space:pre-wrap">{{preview.content}}</pre><img v-else-if="preview.mime.startsWith('image/')" :src="preview.content" alt="归档材料" style="max-width:100%"/><iframe v-else :src="preview.content" title="PDF归档材料" style="width:100%;height:60vh;border:0"/></Modal></template>
